package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen2Test {

  @Test
  public void testFormData_EmptyElements() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    form.elements().add(new Element(new Tag("input")));
    List<Connection.KeyVal> data = form.formData();
    assertTrue(data.isEmpty());
  }

  @Test
  public void testFormData_NoNameAttributes() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    form.elements().add(new Element(new Tag("input")).attr("type", "text"));
    List<Connection.KeyVal> data = form.formData();
    assertTrue(data.isEmpty());
  }

  @Test
  public void testFormData_TypeSelect() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element select = new Element(new Tag("select"));
    select.attr("name", "test");
    select.attr("type", "select");
    Elements options = new Elements();
    options.add(new Element(new Tag("option")).val("Option 1").attr("selected", "true"));
    options.add(new Element(new Tag("option")).val("Option 2"));
    select.children().add(options);
    form.elements().add(select);
    List<Connection.KeyVal> data = form.formData();
    assertEquals(1, data.size());
    assertEquals("test", data.get(0).key());
    assertEquals("Option 1", data.get(0).value());
  }

  @Test
  public void testFormData_TypeCheckbox() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element checkbox = new Element(new Tag("input")).attr("name", "test").attr("type", "checkbox").attr("checked", "true");
    form.elements().add(checkbox);
    List<Connection.KeyVal> data = form.formData();
    assertEquals(1, data.size());
    assertEquals("test", data.get(0).key());
    assertEquals("on", data.get(0).value());
  }

  @Test
  public void testFormData_TypeRadio() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element radio = new Element(new Tag("input")).attr("name", "test").attr("type", "radio").attr("checked", "true");
    form.elements().add(radio);
    List<Connection.KeyVal> data = form.formData();
    assertEquals(1, data.size());
    assertEquals("test", data.get(0).key());
    assertEquals("on", data.get(0).value());
  }

  @Test
  public void testFormData_TypeText() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element text = new Element(new Tag("input")).attr("name", "test").attr("type", "text").val("Hello, World!");
    form.elements().add(text);
    List<Connection.KeyVal> data = form.formData();
    assertEquals(1, data.size());
    assertEquals("test", data.get(0).key());
    assertEquals("Hello, World!", data.get(0).value());
  }

  @Test
  public void testFormData_DisabledElement() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element disabled = new Element(new Tag("input")).attr("name", "test").attr("disabled", "disabled");
    form.elements().add(disabled);
    List<Connection.KeyVal> data = form.formData();
    assertTrue(data.isEmpty());
  }

  @Test
  public void testFormData_NoSubmitAttribute() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element submit = new Element(new Tag("input")).attr("name", "test");
    form.elements().add(submit);
    List<Connection.KeyVal> data = form.formData();
    assertTrue(data.isEmpty());
  }

  @Test
  public void testFormData_Options() {
    FormElement form = new FormElement(new Tag("form"), null, null);
    Element select = new Element(new Tag("select"));
    select.attr("name", "test");
    select.attr("type", "select");
    Elements options = new Elements();
    options.add(new Element(new Tag("option")).val("Option 1").attr("selected", "true"));
    options.add(new Element(new Tag("option")).val("Option 2"));
    select.children().add(options);
    form.elements().add(select);
    List<Connection.KeyVal> data = form.formData();
    assertEquals(1, data.size());
    assertEquals("test", data.get(0).key());
    assertEquals("Option 1", data.get(0).value());
  }
}
